import * as Browser from '@libs/Browser';
import * as ComposerFocusManager from '@libs/ComposerFocusManager';
import ONYXKEYS from '@src/ONYXKEYS';
import type {Modal} from '@src/types/onyx';

let focusedElement: Element | null = null;
let currentActiveElement: Element | null = null;

const focusChange = (newFocusedElement: Element | null) => {
    focusedElement = newFocusedElement;
};

const saveCurrentActiveElement = () => {
    currentActiveElement = document.activeElement;
};

const restoreFocus = () => {
    if (currentActiveElement instanceof HTMLElement) {
        currentActiveElement.focus();
    }
    currentActiveElement = null;
};

document.addEventListener('focusin', (event) => {
    focusChange(event.target as Element);
});

document.addEventListener('focusout', () => {
    focusChange(null);
});

const isFocused = (node: Element) => node === focusedElement;

/**
 * Register a callback to be called when the focus state of the document changes.
 */
function onFocus(callback: () => void, initialize = true) {
    if (initialize) {
        callback();
    }
    return () => {
        document.removeEventListener('focusin', callback);
        document.removeEventListener('focusout', callback);
    };
}

/**
 * Check if the focused element is an input or a text area.
 */
function isInputFocused() {
    return focusedElement instanceof HTMLInputElement || focusedElement instanceof HTMLTextAreaElement;
}

/**
 * Sets the focused state of the Onyx store.
 */
function setFocused(isFocusedValue: boolean) {
    Onyx.set(ONYXKEYS.INPUT_FOCUSED, isFocusedValue);
}

/**
 * Note: We need to be sure that composer is focused when calling this function.
 */
functioncomposerFocusKeepFocusOn(ref: HTMLElement, isFocusedValue: boolean, modal: Modal, onyxFocused: boolean) {
    if (isFocusedValue && !onyxFocused) {
        setFocused(true);
        ref.focus();
    }

    // If the composer is blurred, we need to check if the new focused element is related to the composer.
    // The composer is not blurred if the new focused element is the composer itself or the report actions view.
    // We also need to check if the new focused element is related to the report actions view.
    if (!isFocusedValue && !onyxFocused && !modal.willAlertModalBecomeVisible && !modal.isVisible && focusedElement) {
        if (!ComposerFocusManager.isReadyToFocus()) {
            ref.focus();
        } else {
            ComposerFocusManager.resetReadyToFocus();
        }
    }
}

const callback = (method: () => void) => !Browser.isMobile() && method();

export {composerFocusKeepFocusOn, setFocused as inputFocusChange, callback, isInputFocused, onFocus, isFocused, saveCurrentActiveElement, restoreFocus};
