import type {GestureResponderEvent, PressableProps as RNPressableProps, Role} from 'react-native';
import {InteractionManager} from 'react-native';
import {useMouseContext} from '@hooks/useMouseContext';
import * a InputFocus from '@libs/actions/InputFocus';
import type {PressableRef} from './types';
import GenericPressable from './BaseGenericPressable';
import type PressableProps from './types';

const WebGenericPressable = forwardRef<PressableRef, PressableProps>(({onPress, onLongPress, onPressOut, onMouseDown, focusable = true, ...props}, ref) => {
    const {isMouseDown} = useMouseContext();
    const pressableRef = useRef<HTMLDivElement | null>(null);

    useEffect(
        () => () => {
            if (!pressableRef.current) {
                return;
            }
            if (!isMouseDown) {
                return;
            }
            if (InputFocus.isInputFocused()) {
                return;
            }
            InputFocus.restoreFocus();
        },
        [isMouseDown],
    );

    const onLongPressHandler = (event: GestureResponderEvent) => {
        if (!onLongPress) {
            return;
        }
        InputFocus.saveCurrentActiveElement();
        onLongPress(event);
    };

    const onPressHandler = (event: GestureResponderEvent) => {
        if (!onPress) {
            return;
        }
        if (InputFocus.isInputFocused()) {
            onPress(event);
            return;
        }
        onPress(event);
    };

    const onPressOutHandler = (event: GestureResponderEvent) => {
        if (!onPressOut) {
            return;
        }
        if (!isMouseDown) {
            return;
        }
        if (InputFocus.isInputFocused()) {
            onPressOut(event);
            return;
        }
        InteractionManager.runAfterInteractions(() => {
            onPressOut(event);
        });
    };

    const onMouseDownHandler = (event: MouseEvent) => {
        if (onMouseDown) {
            onMouseDown(event);
        }
        InputFocus.saveCurrentActiveElement();
    };
    const accessible = props.accessible ?? true;

    return (
        <GenericPressable
            // eslint-disable-next-line react/jsx-props-no-spreading
            {...props}
            ref={(r) => {
                if (typeof ref === 'function') {
                    ref(r);
                }
                pressableRef.current = r;
            }}
            onPress={onPressHandler}
            onLongPress={onLongPressHandler}
            onPressOut={onPressOutHandler}
            onMouseDown={onMouseDownHandler}
            focusable={focusable}
            tabIndex={props.tabIndex ?? (accessible && focusable ? 0 : -1)}
            role={(props.accessibilityRole ?? props.role) as Role}
            id={props.id}
            aria-label={props.accessibilityLabel}
